CREATE TABLE course_applications(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,course_id TEXT NOT NULL REFERENCES partner_courses(id),est_size INTEGER CHECK(est_size BETWEEN 1 AND 200),unsure INTEGER NOT NULL DEFAULT 0,contact_user_id TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN('applied','following','confirmed','opened','failed','withdrawn')),confirmed_size INTEGER NOT NULL DEFAULT 0 CHECK(confirmed_size BETWEEN 0 AND 200),seat_price INTEGER CHECK(seat_price IS NULL OR (typeof(seat_price)='integer' AND seat_price>=0)),consultant TEXT NOT NULL DEFAULT '',consultant_note TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,course_id),FOREIGN KEY(tenant_id,contact_user_id) REFERENCES users(tenant_id,id));
